mapper.select:
SELECT COUNT(*)
FROM watchlist
WHERE account_id = #{accountId}

mapper.update:
UPDATE watchlist
SET name = #{name}, updated_at = now()
WHERE watchlist_id = #{watchlistId}

UPDATE watchlist
SET updated_at = now()
WHERE watchlist_id = #{watchlistId}

mapper.select:
SELECT COUNT(*)
FROM watchlist_instrument
WHERE watchlist_id = #{watchlistId}

SELECT EXISTS(
    SELECT 1 FROM watchlist_instrument
    WHERE watchlist_id = #{watchlistId}
    AND instrument_id = #{instrumentId}
)
